class Solution { fun minDifficulty(jobDifficulty:IntArray,d:Int):Int{val n=jobDifficulty.size;if(n<d)return -1;val infinity=1000000000;var dp=IntArray(n+1){infinity};dp[0]=0;for(day in 1..d){val next=IntArray(n+1){infinity};for(jobs in day..n){var maximum=0;for(split in jobs-1 downTo day-1){maximum=maxOf(maximum,jobDifficulty[split]);next[jobs]=minOf(next[jobs],dp[split]+maximum)}};dp=next};return dp[n]} }
